from datetime import datetime, timedelta
import calendar

_MONTH_NAMES = {
    'JAN': 1, 'FEB': 2, 'MAR': 3, 'APR': 4, 'MAY': 5, 'JUN': 6,
    'JUL': 7, 'AUG': 8, 'SEP': 9, 'OCT': 10, 'NOV': 11, 'DEC': 12,
}

_WEEKDAY_NAMES = {
    'SUN': 0, 'MON': 1, 'TUE': 2, 'WED': 3, 'THU': 4, 'FRI': 5, 'SAT': 6,
}


def _parse_single(s: str, names: dict | None, lo_bound: int, hi_bound: int) -> int:
    if not s:
        raise ValueError("empty value")
    if names is not None:
        upper = s.upper()
        if upper in names:
            val = names[upper]
        elif s.isdigit():
            val = int(s)
        else:
            raise ValueError(f"invalid value: {s!r}")
    else:
        if not s.isdigit():
            raise ValueError(f"invalid value: {s!r}")
        val = int(s)
    if val < lo_bound or val > hi_bound:
        raise ValueError(f"value out of range: {val}")
    return val


def _parse_field(field_str: str, min_val: int, max_val: int, names: dict | None) -> set[int]:
    if not field_str:
        raise ValueError("empty field")
    items = field_str.split(',')
    if not items or any(item == '' for item in items):
        raise ValueError("empty item")

    values: set[int] = set()
    for item in items:
        if '/' in item:
            parts = item.split('/')
            if len(parts) != 2:
                raise ValueError("invalid step expression")
            range_part, step_str = parts
            if not step_str or not step_str.isdigit():
                raise ValueError("invalid step value")
            step = int(step_str)
            if step == 0:
                raise ValueError("step must be >= 1")

            if range_part == '*':
                lo, hi = min_val, max_val
            elif '-' in range_part:
                seg = range_part.split('-', 1)
                lo = _parse_single(seg[0], names, min_val, max_val)
                hi = _parse_single(seg[1], names, min_val, max_val)
                if lo > hi:
                    raise ValueError("range start > end")
            else:
                raise ValueError("a/n form not allowed")

            for v in range(lo, hi + 1, step):
                values.add(v)
        elif item == '*':
            values.update(range(min_val, max_val + 1))
        elif '-' in item:
            seg = item.split('-', 1)
            lo = _parse_single(seg[0], names, min_val, max_val)
            hi = _parse_single(seg[1], names, min_val, max_val)
            if lo > hi:
                raise ValueError("range start > end")
            values.update(range(lo, hi + 1))
        else:
            values.add(_parse_single(item, names, min_val, max_val))

    return values


def next_run(expression: str, after: datetime) -> datetime | None:
    fields = expression.split()
    if len(fields) != 5:
        raise ValueError("invalid number of fields")

    minutes = _parse_field(fields[0], 0, 59, None)
    hours = _parse_field(fields[1], 0, 23, None)
    day_field = fields[2]
    month_field = fields[3]
    wday_field = fields[4]

    days = _parse_field(day_field, 1, 31, None)
    months = _parse_field(month_field, 1, 12, _MONTH_NAMES)
    wdays = _parse_field(wday_field, 0, 7, _WEEKDAY_NAMES)

    # Normalize 7 -> 0 for day-of-week
    if 7 in wdays:
        wdays.discard(7)
        wdays.add(0)

    day_unspecified = (day_field == '*')
    wday_unspecified = (wday_field == '*')

    start = after.replace(second=0, microsecond=0) + timedelta(minutes=1)
    max_year = after.year + 10

    sorted_minutes = sorted(minutes)
    sorted_hours = sorted(hours)
    sorted_months = sorted(months)

    for year in range(start.year, max_year + 1):
        for month in sorted_months:
            if year == start.year and month < start.month:
                continue
            num_days = calendar.monthrange(year, month)[1]
            for day in range(1, num_days + 1):
                if year == start.year and month == start.month and day < start.day:
                    continue

                # Check day / weekday matching rules
                if not (day_unspecified and wday_unspecified):
                    dow = datetime(year, month, day).isoweekday() % 7  # 0=Sun,1=Mon,...,6=Sat
                    if day_unspecified:
                        if dow not in wdays:
                            continue
                    elif wday_unspecified:
                        if day not in days:
                            continue
                    else:
                        if day not in days and dow not in wdays:
                            continue

                # Find the earliest matching time on this day
                for hour in sorted_hours:
                    for minute in sorted_minutes:
                        candidate = datetime(year, month, day, hour, minute)
                        if candidate >= start:
                            return candidate

    return None
